#include<bits/stdc++.h>
#define int long long
using namespace std;
int w[1111][1111],m[1111][1111];
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
	cin>>n;
	for(int i=1;i<=n;i++){
		for(int j=1;j<=n;j++){
			cin>>w[i][j];
		}
	}
	for(int i=1;i<=n;i++){
		for(int j=i;j<=n;j++){
			w[i][j]=1;
			for(int k=i+1;k<j;k++){
				if(m[i][k]&&m[k][j]&&(w[i][k]||w[j][k])){
					w[i][j]=1;
				}else{
					w[i][j]=0;
					break;
				}
			}
		}
	}
	for(int i=1;i<=n;i++){
		if(m[i][i]){
			cout<<i<<endl;
		}
	}
	return 0;
}
